// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.24;

// Uncomment this line to use console.log
// import "hardhat/console.sol";
import "./IFunToken.sol";
import "@openzeppelin/contracts/utils/Strings.sol";
import "@openzeppelin/contracts/token/ERC20/ERC20.sol";

contract TestERC20TransferThenPrecompileSend {
    address erc20;

    constructor(address erc20_) {
        erc20 = erc20_;
    }

    function erc20TransferThenPrecompileSend(
        address payable transferRecipient,
        uint256 transferAmount,
        string memory precompileRecipient,
        uint256 precompileAmount
    ) public {
        require(
            ERC20(erc20).transfer(transferRecipient, transferAmount),
            "ERC-20 transfer failed"
        );

        uint256 sentAmount = FUNTOKEN_PRECOMPILE.sendToBank(
            erc20,
            precompileAmount,
            precompileRecipient
        );

        require(
            sentAmount == precompileAmount,
            string.concat(
                "IFunToken.sendToBank succeeded but transferred the wrong amount",
                "sentAmount ",
                Strings.toString(sentAmount),
                "expected ",
                Strings.toString(precompileAmount)
            )
        );
    }
}

contracts/TestERC20TransferWithFee.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";

contract TestERC20TransferWithFee is ERC20 {
    uint256 constant FEE_PERCENTAGE = 10;

    constructor(string memory name, string memory symbol)
    ERC20(name, symbol) {
        _mint(msg.sender, 1000);
    }

    function transfer(address to, uint256 amount) public virtual override returns (bool) {
        address owner = _msgSender();
        require(amount > 0, "Transfer amount must be greater than zero");

        uint256 fee = (amount * FEE_PERCENTAGE) / 100;
        uint256 recipientAmount = amount - fee;

        _transfer(owner, address(this), fee);
        _transfer(owner, to, recipientAmount);

        return true;
    }
}

contracts/TestFunTokenPrecompileLocalGas.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "./IFunToken.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

contract TestFunTokenPrecompileLocalGas {
    address erc20;

    constructor(address erc20_) {
        erc20 = erc20_;
    }

    // Calls sendToBank of the FunToken Precompile with the default gas.
    // Internal call could use all the gas for the parent call.
    function callBankSend(
        uint256 amount,
        string memory bech32Recipient
    ) public {
        uint256 sentAmount = FUNTOKEN_PRECOMPILE.sendToBank(
            erc20,
            amount,
            bech32Recipient
        );
        require(
            sentAmount == amount,
            string.concat(
                "IFunToken.sendToBank succeeded but transferred the wrong amount",
                "sentAmount ",
                Strings.toString(sentAmount),
                "expected ",
                Strings.toString(amount)
            )
        );
    }

    // Calls sendToBank of the FunToken Precompile with the gas amount set in parameter.
    // Internal call should fail if the gas provided is insufficient.
    function callBankSendLocalGas(
        uint256 amount,
        string memory bech32Recipient,
        uint256 customGas
    ) public {
        uint256 sentAmount = FUNTOKEN_PRECOMPILE.sendToBank{gas: customGas}(
            erc20,
            amount,
            bech32Recipient
        );
        require(
            sentAmount == amount,
            string.concat(
                "IFunToken.sendToBank succeeded but transferred the wrong amount",
                "sentAmount ",
                Strings.toString(sentAmount),
                "expected ",
                Strings.toString(amount)
            )
        );
    }
}

